/**
 * Wiring to custom elements that declare the wc-bindable protocol:
 *   static wcBindable = { protocol: "wc-bindable", version: 1,
 *     properties: [{ name, event, getter?, semantics? }],   // element → state
 *     inputs:     [{ name, attribute? }],                    // state → element
 *     commands:   [{ name, async? }] }                       // state invokes
 * Property bindings take their direction and initial authority from the declaration;
 * `command.<m>:` subscribes a method to a command token; `eventToken.<p>:` fires an event
 * token when the element dispatches that property's event; `...:` spreads a state object
 * over every declared property and input.
 */
import type { Engine } from "../engine";
import { raise, M } from "../messages";
import { hooks } from "../hooks";
import type { StateRow } from "../list";
import { adopt, Binding, failSpec, K_CUSTOM, type Block, type Spec } from "./view";
import { pipe } from "./filters";
// (view.ts imports this module too: the cycle is fine, everything here is used at call time)

interface PropertyDecl {
  event: string;
  getter: ((e: Event) => unknown) | null;
  /** `semantics: "event"`: an occurrence, written even when equal to the current value. */
  occurrence: boolean;
}

export interface Bindable {
  properties: Map<string, PropertyDecl>;
  /** The settable members. Their `attribute` hint is not used: the element reflects its own attributes. */
  inputs: Set<string>;
  commands: Set<string>;
}

const bindableByClass = new WeakMap<CustomElementConstructor, Bindable | null>();

/** The element's wc-bindable declaration (null when it has none), cached per class. */
export function readBindable(cls: CustomElementConstructor): Bindable | null {
  if (bindableByClass.has(cls)) return bindableByClass.get(cls)!;
  const decl = (cls as any).wcBindable;
  let out: Bindable | null = null;
  if (decl !== null && typeof decl === "object" && decl.protocol === "wc-bindable" && Number.isInteger(decl.version) && decl.version >= 1) {
    out = { properties: new Map(), inputs: new Set(), commands: new Set() };
    for (const p of decl.properties ?? []) {
      out.properties.set(p.name, { event: p.event, getter: typeof p.getter === "function" ? p.getter : null, occurrence: p.semantics === "event" });
    }
    for (const i of decl.inputs ?? []) out.inputs.add(i.name);
    for (const c of decl.commands ?? []) if (c !== null && typeof c === "object" && typeof c.name === "string") out.commands.add(c.name);
  }
  bindableByClass.set(cls, out);
  return out;
}

/** The registry that defines `el`: a scoped one (`attachShadow({ customElementRegistry })`) or the global one. */
export const registryOf = (el: Element): CustomElementRegistry =>
  ((el as any).customElementRegistry as CustomElementRegistry | null | undefined) ?? customElements;

/**
 * Runs `attach` (for spec `s`) once the element's class is defined (at once when it already is) and
 * upgraded, unless its block went away in the meantime (`pending`). A native element has no definition to wait
 * for: it is attached at once (and refused there, as a custom element with no declaration is).
 */
export function whenDefined(engine: Engine, s: Spec, el: Element, owner: Block | null, attach: (bindable: Bindable | null) => void, later = false): void {
  const tag = el.localName;
  if (!tag.includes("-")) return attach(null);
  const r = registryOf(el);
  // a row built in a fragment takes the registry of the shadow root it goes into (a scoped one)
  // when it is placed, in this drain: wait for that before waiting for a definition
  if (!later && !el.isConnected && r.get(tag) === undefined && "customElementRegistry" in el) {
    queueMicrotask(() => whenDefined(engine, s, el, owner, attach, true));
    return;
  }
  const run = (): void => {
    const cls = r.get(tag);
    r.upgrade(el);
    attach(cls ? readBindable(cls) : null);
  };
  if (!later && r.get(tag) !== undefined) return run();
  // a row gone while it waited for its registry waits for nothing (its block's cleanups have run)
  if (owner !== null && !owner.alive) return;
  // later, outside any drain: a failure is the binding's; it and what was applied are reported by
  // a drain (one for every element the definition upgrades: one `$renderedCallback`)
  pending(r.whenDefined(tag), owner, () => {
    try {
      run();
    } catch (error) {
      failSpec(engine, error, s, el);
    }
    engine.schedule();
  });
}

/**
 * Runs `fn` once `p` settles, unless `owner` went away first. Its own scope: the reaction holds
 * only `f`, so a removed row of a tag never defined keeps nothing alive.
 */
function pending(p: Promise<unknown>, owner: Block | null, fn: () => void): void {
  let f: (() => void) | null = fn;
  if (owner !== null) (owner.cleanups ??= []).push(() => {
    f = null;
  });
  void p.then(() => f?.());
}

/** A property binding on a member of a custom element's wc-bindable declaration. */
export function attachProperty(engine: Engine, spec: Spec, el: Element, name: string, pattern = spec.pattern!,
  row: StateRow | null, owner: Block | null, bd: Bindable): Binding {
  const out = bd.properties.get(name) ?? null;
  const input = bd.inputs.has(name);
  // enableDirectionalInitialSync off (3.x opt-out): no member checks (and no init= / sync=, see
  // plan.ts); state wins every initial sync, output-only included
  const directional = engine.directional;
  if (directional && out === null && !input) raise(M.MemberUndeclared, [name]);
  // what the member's shape allows: output-only takes element / none, input-only state / none, two-way any
  const init = spec.init;
  const refused = out === null ? init === "element" || init === "auto" : !input && (init === "state" || init === "auto");
  if (refused) raise(M.InitIncompatible, [init, name]);
  if (spec.sync === "connect" && out === null) raise(M.SyncConnectNeedsOutput, [name]);
  const outputOnly = directional && out !== null && !input;
  const b = new Binding(engine, K_CUSTOM, el, name, pattern, row, owner, spec.filters, undefined);
  b.inFilters = spec.inFilters;
  // state → element (every member but an output-only one)
  adopt(engine, b, !outputOnly);
  // element → state (a declared property)
  if (out !== null && !spec.ro) {
    el.addEventListener(out.event, (e) => {
      let v: unknown;
      if (out.getter !== null) v = out.getter(e);
      else {
        v = (e as CustomEvent).detail;
        // the protocol's default getter: diagnostics tells the two shapes it can see are wrong
        if (!out.occurrence) hooks.detail?.(el, name, v);
      }
      if (b.applying && Object.is(v, b.value)) return; // our own write echoing back
      v = pipe(b.inFilters, v);
      // the element already shows this value: the apply this write causes must not echo it
      // back to the element it came from
      if (b.filters === null) b.value = v;
      engine.write(b.pattern, b.row, v, out.occurrence, true);
    });
  }
  // initial authority: output-only members seed state from the element, others the other way
  const authority = init ?? (outputOnly ? "element" : "state");
  if (authority === "state") {
    if (!outputOnly) engine.applyBinding(b);
  } else if (authority === "element" || authority === "auto") {
    const seed = (): void => {
      if (owner !== null && !owner.alive) return;
      if (authority === "auto" && engine.readUntracked(b.pattern, b.row) !== undefined) {
        if (!outputOnly) engine.applyBinding(b);
        return;
      }
      const snapshot = (el as any)[name];
      if (b.filters === null) b.value = snapshot; // seeded from the element: nothing to write back
      engine.write(b.pattern, b.row, snapshot, false, true);
    };
    if (spec.sync === "connect" && !el.isConnected) void Promise.resolve().then(seed);
    else seed();
  }
  return b;
}

function noBindable(id: M, el: Element, what: string): never {
  raise(id, [el.localName, what]);
}

/**
 * `command.<method>: $command.<token>` — the element's method subscribes to the token. A native
 * element (no declaration) is called the way the native-commands add-on says, when installed.
 */
export function attachCommand(engine: Engine, spec: Spec, el: Element, owner: Block | null, bd: Bindable | null): void {
  const method = spec.name;
  // (the path, "$command.<token>")
  const token = engine.command(spec.token!.slice(9));
  const call = bd === null ? hooks.nativeCommand?.(el, method) : null;
  if (!call) {
    if (bd === null) noBindable(M.NoBindable, el, `command.${method}`);
    if (!bd.commands.has(method)) raise(M.NoCommand, [el.localName, method]);
  }
  const ref = new WeakRef(el);
  const fn = (...args: unknown[]): unknown => {
    const target = ref.deref() as any;
    if (target === undefined) {
      unsubscribe();
      return undefined;
    }
    // detached for now (a route hidden with its nodes kept): not called, still subscribed
    return target.isConnected ? (call ? call(target, args) : target[method](...args)) : undefined;
  };
  const unsubscribe = token.subscribe(fn);
  if (owner !== null) (owner.cleanups ??= []).push(unsubscribe);
}

/** `eventToken.<property>: <token>` — the property's event fires the event token. */
export function attachEventToken(engine: Engine, spec: Spec, el: Element, row: StateRow | null, bd: Bindable | null): void {
  const prop = spec.name;
  if (bd === null) noBindable(M.NoBindable, el, `eventToken.${prop}`);
  const decl = bd.properties.get(prop);
  if (decl === undefined) raise(M.NoProperty, [el.localName, prop]);
  const name = spec.token!;
  el.addEventListener(decl.event, (e) => {
    if (spec.prevent) e.preventDefault();
    if (spec.stop) e.stopPropagation();
    try {
      engine.fireEventToken(name, e, row);
    } catch (error) {
      console.error(error);
    }
  });
}

/** `...: path` — one property binding per declared property and input (explicit bindings win). */
export function attachSpread(engine: Engine, spec: Spec, el: Element, row: StateRow | null, owner: Block | null, bd: Bindable | null): void {
  if (bd === null) noBindable(M.SpreadNoBindable, el, `"...: ${spec.pattern!.path}"`);
  const names = new Set([...bd.properties.keys(), ...bd.inputs]);
  for (const name of names) {
    if (spec.exclude?.includes(name)) continue;
    const p = engine.pattern(`${spec.pattern!.path}.${name}`);
    const r = p.depth === 0 ? null : row;
    attachProperty(engine, { ...spec, init: null, sync: null }, el, name, p, r, owner, bd);
  }
}
